"""
Tools for inspecting libraries that utilize contracts.
"""

from __future__ import annotations

from types import ModuleType
from typing import Any, Callable

from taf.internal.contracts.contracts import TafContract
from taf.internal.contracts.contracts import contracts as contracts_list


def find_all_providers(module: ModuleType, contract) -> dict[str, Any]:
    """Find all objects (classes) in the given module that provide the given contract.

    This is a soft check: it looks for classes that have an attribute with the
    same name as required for the contract methods. It does not check if this
    attribute is in fact a method.

    It does not look deep: only the global module attributes are checked.
    Nested classes, or classes from submodules are not found unless they are
    assigned globaly in the given module.

    You can use this to ensure that every provider of a given kind is covered
    by the tests::

        import pytest
        import taf.example.library
        from taf.internal.contracts import (
            call_provider,
            find_all_providers,
            Ssh,
        )

        ssh_providers = find_all_providers(taf.example.library, Ssh)

        @pytest.mark.parametrize("ssh_provider", ssh_providers.values())
        def test_ssh_providers(ssh_provider):
            obj_to_test = ssh_provider(...)

            ...

            # Test the object thoroughly
            assert call_provider(obj_to_test, Ssh) == ...

    This way you will never miss a class in your tests.

    :param str module: The name of the module to search.
    :param contract: The contract to search for. If omitted, returns all
        providers in a module.
    :return: A mapping of attribute names (class names) of the found values and
        the values (classes) themselves.
    """
    method_name = f"__taf_contract_{contract.__name__.lower()}__"
    return {
        attribute: obj
        for attribute, obj in module.__dict__.items()
        if hasattr(obj, method_name)
    }


def get_contract_by_name(name: str) -> Any:
    """Return the contract class by name, case sensitive.

    If the contract with the given name is not found, returns ``None``
    """
    import taf.internal.contracts as contracts

    contract = getattr(contracts, name, None)

    if contract is None or not isinstance(contract, TafContract):
        return None
    else:
        return contract


def contract_class_from_func(func: Callable) -> Any:
    """Given a function, return the protocol it provides for.

    This is based on the function's name. If the function does not have a name
    in the ``__taf_contract_<contract-name>__`` format, or no contract named
    ``<contract-name>`` exists - returns ``None``.
    """
    name = func.__name__
    prefix = "__taf_contract_"
    suffix = "__"

    if not (name.startswith(prefix) and name.endswith(suffix)):
        return None

    contract_name = name.removeprefix(prefix).removesuffix(suffix)
    any(
        (found := contract).__name__.lower() == contract_name
        for contract in contracts_list
    )

    return found
